<?php
class Reporte_cortesias_model extends CI_Model{
 public function usuario_tiene_rol($u,$r){return !empty($this->db->query("SELECT 1 x FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$u,(int)$r))->row_array());}
 public function listas(){return array('usuarios'=>$this->db->query("SELECT usuario_id,usuario_nombre,usuario_login FROM usuario ORDER BY usuario_nombre")->result_array(),'rutas'=>$this->db->query("SELECT ruta_id,ruta_nombre FROM ruta ORDER BY ruta_nombre")->result_array(),'motivos'=>$this->db->query("SELECT cortesiamotivo_id,cortesiamotivo_nombre FROM cortesia_motivo WHERE estado_id=1 ORDER BY cortesiamotivo_nombre")->result_array());}
 private function where($f,&$p){$w="DATE(cb.cortesia_fechahora) BETWEEN ? AND ? AND cb.estado_id=1";$p=array($f['desde'],$f['hasta']);if($f['usuario_id']>0){$w.=" AND cb.usuario_id=?";$p[]=$f['usuario_id'];}if($f['ruta_id']>0){$w.=" AND v.ruta_id=?";$p[]=$f['ruta_id'];}if($f['motivo_id']>0){$w.=" AND cb.cortesiamotivo_id=?";$p[]=$f['motivo_id'];}return $w;}
 public function resumen($f){$p=array();$w=$this->where($f,$p);$sql="SELECT COUNT(*) cortesias,COALESCE(SUM(cb.tarifa_original),0) valor_tarifario,COALESCE(SUM(cb.importe_cobrado),0) cobrado,COALESCE(SUM(cb.tarifa_original-cb.importe_cobrado),0) beneficio FROM pasaje_cortesia_bitacora cb LEFT JOIN viaje v ON v.viaje_id=cb.viaje_id WHERE $w";return $this->db->query($sql,$p)->row_array();}
 public function detalle($f){$p=array();$w=$this->where($f,$p);$sql="SELECT cb.cortesiabitacora_id,cb.cortesia_fechahora fecha,p.pasaje_numero ticket,p.pasaje_nombre pasajero,p.pasaje_documento documento,COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)) ruta,COALESCE(NULLIF(cb.cortesia_motivo,''),cm.cortesiamotivo_nombre,'SIN MOTIVO') motivo,cb.tarifa_original,cb.importe_cobrado,COALESCE(NULLIF(u.usuario_nombre,''),u.usuario_login,CONCAT('ID ',cb.usuario_id)) usuario FROM pasaje_cortesia_bitacora cb INNER JOIN pasaje p ON p.pasaje_id=cb.pasaje_id LEFT JOIN viaje v ON v.viaje_id=cb.viaje_id LEFT JOIN ruta r ON r.ruta_id=v.ruta_id LEFT JOIN cortesia_motivo cm ON cm.cortesiamotivo_id=cb.cortesiamotivo_id LEFT JOIN usuario u ON u.usuario_id=cb.usuario_id WHERE $w ORDER BY cb.cortesia_fechahora DESC,cb.cortesiabitacora_id DESC";return $this->db->query($sql,$p)->result_array();}
}
